style.css:
@-moz-document domain("youtube.com") {
/* 1. Deep Midnight Background Override */
    html, html[system-tracker], [dark], ytd-app {
        background-color: #0b0c10 !important;
    }
    
    ytd-masthead, #background.ytd-masthead {
        background: #1f2833 !important;
    }

    /* 2. Neon Purple Accents & Text */
    ytd-guide-entry-renderer[active] .title.ytd-guide-entry-renderer,
    ytd-button-renderer.style-suggestive[is-paper-button] {
        color: #bb86fc !important;
    }
    
    /* 3. Glowing Neon Video Progress Bar */
    .ytp-play-progress, .ytp-scrubber-button {
        background: #bb86fc !important;
        box-shadow: 0 0 8px #bb86fc, 0 0 15px #bb86fc !important;
    }
    
    /* 4. Sleek Rounded Modern Player */
    .html5-video-player, #player-container, ytd-playlist-thumbnail {
        border-radius: 12px !important;
        overflow: hidden !important;
    }
    
    /* 5. Minimalist Clean Sidebar (Removes footer links) */
    #footer.ytd-guide-renderer {
        display: none !important;
    }
    
    /* 6. Text Contrast Enhancements */
    #video-title.ytd-rich-grid-media, #channel-name.ytd-video-meta-block {
        color: #c5c6c7 !important;
    }
}
